/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-06 (#10): new file - the preDeploy hook of the deploy pipeline (step 3): a validator
 *   registered with RED.hooks.add can reject a deployment (400 deploy_rejected) before anything
 *   is saved; a failure or a timeout of the validator stops the deployment (503
 *   deploy_hook_failed / deploy_hook_timeout, fail-closed); the postDeploy hook (step 11): a
 *   notification after the configuration was saved or reloaded, the dictionary of start.status
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * The hooks of the deploy pipeline (Z-06, design/engine-extensions/ZASADY.md section 2.3 A, step 3).
 *
 * Handlers are registered only with `RED.hooks.add("preDeploy[.label]", fn)` (a plugin or a
 * node; the `hooks` setting of settings.js does not accept them). They are not run by
 * `hooks.trigger()`: the pipeline reads them with `hooks.handlers()` and runs them here, because
 * a deployment needs a deadline for the whole chain, a limit for a handler that does not
 * finish, the identity of the handler in logs, and a result per handler.
 *
 * ## preDeploy
 *
 * `fn(event)` or `fn(event, done)`; handlers run one by one in the order of registration, under
 * the deploy lock, before anything changes. The first result that is not an acceptance ends
 * the chain. `event` is deeply frozen (`PreDeployEvent`):
 *
 *   type       "full" | "nodes" | "flows" | "reload" | "load" (the requested type; "reload" and "load" are
 *              validated on the content of storage and `rev` is its revision)
 *   source     "api" | "internal" (never "storage": a reload after a change in storage has no preDeploy)
 *   operation  "setFlows" | "addFlow" | "updateFlow" | "deleteFlow"
 *   flowId     the flow of the single-flow api (addFlow: the new id)
 *   created    updateFlow with deploy.putCreatesFlow: whether the flow is created
 *   flows      the resulting flow configuration (an array) - a copy without the `credentials`
 *              of any element and without the `value` of the `env` entries of type "cred"
 *   activeRev  the revision of the running configuration (null when there is none)
 *   rev        reload only: the revision in storage
 *   user       `{username, permissions}` or null
 *   deadline   Date.now() + deploy.hookTimeout, shared by the whole chain
 *   signal     an AbortSignal aborted with the reason "timeout" at the deadline (not frozen)
 *
 * Results:
 *   - accept: the function returns (or its promise resolves with) anything but `false`,
 *     or calls `done()` / `done(undefined)`;
 *   - reject (the intended rejection): `false` / `done(false)`, or an `Error` with
 *     `status === 400` thrown, rejected or passed to `done`: 400 `deploy_rejected` with
 *     `message` (the message of the error), `reason` (its `code`, a short identifier) and
 *     `details` (its `details`, a plain object or array up to 8 KB);
 *   - failure: anything else - another error, `Promise.reject()`, `done("x")`, a mutation of
 *     the frozen event: 503 `deploy_hook_failed` with a constant message; the reason is only
 *     in the log;
 *   - no result before the deadline: 503 `deploy_hook_timeout`.
 *
 * Calling style: `fn.length <= 1` - `fn(event)`, the returned value or promise is the result
 * (a function of length 0, for example `async () => {}`, is called like this too); `>= 2` -
 * `fn(event, done)`; a returned promise also counts, the first result wins, a returned value
 * that is not a promise is ignored.
 *
 * The handler must respect `signal` / `deadline` and give its own network calls a limit: after
 * the deadline the pipeline does not wait, but a call that has not finished keeps the handler
 * "busy" - the next deployment is rejected at once with 503 `deploy_hook_timeout` without calling
 * it (SEC-103) until that call ends or the process restarts (fail-closed). A handler must not
 * start a deployment (SEC-104): it would wait for the lock held by its own deployment.
 *
 * ## postDeploy
 *
 * `fn(event)` or `fn(event, done)`, called once for every configuration that was saved or reloaded
 * (the active configuration was replaced), also when the deployment then ended with an error, and
 * never for a configuration that was not saved (a rejection, a limit, 409/400, a failed save). It
 * runs after the result of the deployment, asynchronously (setImmediate), without delaying it or
 * the next deployment; all handlers are started in parallel in the order of registration, a returned
 * value is ignored, a failure is only logged (warning). The state of the instance at that moment is
 * usually "deploying" (the start of the flows goes on): a handler must not assume "ready"; the final
 * result of a start is in the `instance:state` event and in `deploy-start-result`. The event is deeply
 * frozen (`PostDeployEvent`):
 *
 *   rev         the revision of the whole configuration after the save
 *   type        "full" | "nodes" | "flows" | "reload"
 *   source      "api" | "internal" | "storage" (a reload after a change in storage: a handler that
 *               publishes the change to other instances MUST skip "storage", or the instances
 *               reload each other without end)
 *   operation   "setFlows" | "addFlow" | "updateFlow" | "deleteFlow", null for "storage"
 *   flowId      the flow of the single-flow api, otherwise null
 *   user        `{username, permissions}` or null
 *   reloadType  reload only: "full" | "diff"
 *   start       `{status, errors?}` - see classifyStart
 *   error       `{code}` - an error after the save that is not about the start (D24)
 *   deadline, signal  `deploy.hookTimeout` after the call; the signal is aborted with "timeout" and
 *               a warning is logged for a handler that has not finished - it is not interrupted
 *
 * At most 10 calls of a handler can be unfinished: the next ones are skipped with a warning
 * (SEC-103). A handler that deploys starts an endless chain of deployments (SEC-104).
 *
 * `preDeploy` validates deployments made through the API and the runtime API of this instance;
 * it is not a security boundary (SEC-105): a reload after a change in storage, a project switch,
 * the start of the process and code running in the process (`RED.hooks.remove`) bypass it.
 * @module
 */

const { log, hooks } = require("@node-red/util");

// deploy.hookTimeout: the default (ms) and the largest value setTimeout accepts
const DEFAULT_HOOK_TIMEOUT = 30000;
const MAX_HOOK_TIMEOUT = 2147483647;

const MAX_RESPONSE_MESSAGE = 1000;
const MAX_LOG_MESSAGE = 200;
const MAX_DETAILS_BYTES = 8 * 1024;
// postDeploy: the most unfinished calls of one handler (SEC-103)
const MAX_UNFINISHED_POST_CALLS = 10;
const REASON_PATTERN = /^[A-Za-z0-9_.:-]{1,64}$/;
// Control characters, the C1 controls, U+2028/U+2029 and the bidirectional overrides and
// isolates (SEC-102, SEC-106)
const UNSAFE_CHARACTERS = /[\u0000-\u001F\u007F-\u009F\u2028\u2029\u202A-\u202E\u2066-\u2069]/g;

// The calls of a handler that have not ended, by the object of the handler from hooks.handlers()
// (a handler added again under the same label is another object): SEC-103
const runningCalls = new WeakMap();
// The number of unfinished postDeploy calls by handler
const unfinishedPostCalls = new WeakMap();

let runtime;

function init(_runtime) {
    runtime = _runtime;
}

/**
 * The text of the message catalog (runtime.json); the key itself when the catalog is not loaded.
 */
function catalog(key, params) {
    const text = log._(key, params);
    return typeof text === "string" && text !== "" ? text : key;
}

/**
 * Whether `value` is a valid `deploy.hookTimeout`: a finite number of ms, > 0 and
 * <= 2147483647 (the limit of setTimeout).
 * @param {*} value
 * @return {boolean}
 */
function isValidHookTimeout(value) {
    return typeof value === "number" && Number.isFinite(value) && value > 0 && value <= MAX_HOOK_TIMEOUT;
}

/**
 * The limit of the preDeploy chain (`deploy.hookTimeout`, ms), read at every deployment; an
 * invalid or missing value gives the default (the warning is logged once, at init, by
 * api/flows.js).
 * @return {number}
 */
function getHookTimeout() {
    const deploySettings = runtime && runtime.settings && runtime.settings.deploy;
    const value = deploySettings && deploySettings.hookTimeout;
    return isValidHookTimeout(value) ? value : DEFAULT_HOOK_TIMEOUT;
}

/**
 * Text for a response or a log: control characters, C1 controls, line/paragraph separators and
 * bidirectional overrides are replaced by a space, the length is limited. `String(x)` runs in a
 * `try` (a `toString` that throws gives `fallback`); `undefined`, `null` and a text that is empty
 * afterwards give `fallback` too.
 * @param {*} value
 * @param {number} limit - the maximum length
 * @param {string} fallback
 * @return {string}
 */
function sanitizeText(value, limit, fallback) {
    if (value === undefined || value === null) {
        return fallback;
    }
    let text;
    try {
        text = typeof value === "string" ? value : String(value);
    } catch (err) {
        return fallback;
    }
    text = text.replace(UNSAFE_CHARACTERS, " ");
    if (text.length > limit) {
        text = text.slice(0, limit);
    }
    return text.trim() === "" ? fallback : text;
}

/**
 * The user of the event: `{username, permissions}` or null (a copy, no other field).
 * @param {Object} user - the user of the request
 * @return {Object|null}
 */
function sanitizeUser(user) {
    if (!user || typeof user !== "object") {
        return null;
    }
    let permissions = null;
    if (typeof user.permissions === "string") {
        permissions = sanitizeText(user.permissions, 256, null);
    } else if (Array.isArray(user.permissions)) {
        permissions = Object.freeze(user.permissions.filter(p => typeof p === "string").map(p => sanitizeText(p, 256, "")));
    }
    return Object.freeze({
        username: typeof user.username === "string" ? sanitizeText(user.username, 256, null) : null,
        permissions: permissions
    });
}

// The replacer of copyForHook: SEC-101
function withoutCredentials(key, value) {
    if (key === "credentials") {
        return undefined;
    }
    if (key === "env" && Array.isArray(value)) {
        return value.map(function(entry) {
            if (entry && typeof entry === "object" && entry.type === "cred") {
                const copy = Object.assign({}, entry);
                delete copy.value;
                return copy;
            }
            return entry;
        });
    }
    return value;
}

function deepFreeze(root) {
    const stack = [root];
    while (stack.length > 0) {
        const value = stack.pop();
        if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
            Object.freeze(value);
            Object.keys(value).forEach(function(key) { stack.push(value[key]) });
        }
    }
    return root;
}

/**
 * The copy of a flow configuration for a handler (SEC-101, A27): one pass of
 * `JSON.stringify` with a replacer that drops the `credentials` of any element and the `value`
 * of the `env` entries of type "cred" (also inside the result of a `toJSON`), then `JSON.parse`
 * and a deep freeze. The deployed configuration is computed independently of this copy (I4).
 * @param {Array} flows
 * @return {Array} the frozen copy
 * @throws {Error} when the configuration cannot be serialised (a cycle, a BigInt)
 */
function copyForHook(flows) {
    return deepFreeze(JSON.parse(JSON.stringify(flows, withoutCredentials)));
}

// The errors that the pipeline answers with (400/503 built here): the last-resort catch of
// runPreDeploy passes them on and turns every other exception into deploy_hook_failed
const responseErrors = new WeakSet();

// The stack of what a handler threw, for the debug log. What a handler throws can be anything - an
// Error with a getter that throws, a revoked Proxy - so nothing of it is read outside a try
function stackText(value) {
    try {
        return value && value.stack ? String(value.stack) : "no stack";
    } catch (err) {
        return "no stack";
    }
}

// An Error that says "the configuration is wrong, do not retry": the intended rejection
function isIntendedRejection(error) {
    return error instanceof Error && error.status === 400;
}

/**
 * The outcome of one call, from what the handler produced.
 * kind "value": the returned value or the value a returned promise resolved with
 * kind "done": the argument of `done`
 * kind "error": thrown, or the reason a returned promise was rejected with
 * @return {{accept: true}|{reject: (false|Error)}|{failure: *}}
 */
function interpret(kind, value) {
    try {
        return interpretResult(kind, value);
    } catch (err) {
        // reading `status` of what the handler threw failed (a getter that throws, a revoked Proxy)
        return { failure: err };
    }
}

function interpretResult(kind, value) {
    if (kind === "value") {
        return value === false ? { reject: false } : { accept: true };
    }
    if (kind === "done") {
        if (value === undefined) {
            return { accept: true };
        }
        if (value === false) {
            return { reject: false };
        }
    }
    return isIntendedRejection(value) ? { reject: value } : { failure: value };
}

/**
 * Calls a handler in its style (see the module description) and passes the first result to
 * `finish(kind, value)`: kind "value" (the returned value or what a returned promise resolved
 * with), "done" (the argument of `done`) or "error" (thrown, or the reason a returned promise was
 * rejected with). Later results are ignored.
 */
function invoke(handler, event, finish) {
    let finished = false;
    function settle(kind, value) {
        if (finished) {
            return;
        }
        finished = true;
        try {
            finish(kind, value);
        } catch (err) {
            // `finish` has its own protection; this is the last resort - an exception must never leave a
            // `then` callback of the handler's promise, where it would be an unhandled rejection
            try {
                log.warn(catalog("deploy.hook-failed-log", { id: sanitizeText(handler.id, 100, "hook"), code: "-", message: sanitizeText(err && err.message, MAX_LOG_MESSAGE, "no message") }));
            } catch (logError) {
                // nothing more can be done
            }
        }
    }
    function follow(result) {
        let then;
        try {
            then = result && typeof result.then === "function" ? result.then : null;
        } catch (err) {
            settle("error", err);
            return true;
        }
        if (!then) {
            return false;
        }
        try {
            then.call(result, function(value) { settle("value", value) }, function(error) { settle("error", error) });
        } catch (err) {
            settle("error", err);
        }
        return true;
    }
    try {
        if (handler.cb.length >= 2) {
            follow(handler.cb(event, function(value) { settle("done", value) }));
        } else {
            const result = handler.cb(event);
            if (!follow(result)) {
                settle("value", result);
            }
        }
    } catch (err) {
        settle("error", err);
    }
}

/**
 * Starts one call of a preDeploy handler. The returned promise never rejects: it resolves with the
 * outcome (see interpret) of the first result.
 * `call.abandoned` is set by the chain when it stopped waiting (deadline); a result that
 * arrives after that is logged as late and has no effect on any later deployment (I14).
 * @return {{promise: Promise, call: Object}}
 */
function startCall(handler, event) {
    const call = { startedAt: Date.now(), abandoned: false, ended: false };
    runningCalls.set(handler, call);
    const promise = new Promise(function(resolve) {
        invoke(handler, event, function(kind, value) {
            call.ended = true;
            if (runningCalls.get(handler) === call) {
                runningCalls.delete(handler);
            }
            if (call.abandoned) {
                log.warn(catalog("deploy.hook-late", { id: sanitizeText(handler.id, 100, "preDeploy") }));
            }
            // interpret does not throw (an unreadable result is a failure)
            resolve(interpret(kind, value));
        });
    });
    return { promise: promise, call: call };
}

function responseError(code, status, message) {
    const err = new Error(message);
    err.code = code;
    err.status = status;
    responseErrors.add(err);
    return err;
}

/**
 * The 400 `deploy_rejected` error for an intended rejection: a new Error with only the allowed
 * fields (the `remote`, `rev`, `errors` and `stack` of the handler's error never reach the
 * response - I6).
 * @param {false|Error} rejected - `false`, or the Error with status 400
 * @param {string} id - the hook id, for the log
 */
function toRejection(rejected, id) {
    const defaultMessage = catalog("deploy.rejected-default");
    let message = defaultMessage;
    let reason = "rejected";
    let details;
    if (rejected !== false) {
        let rawMessage;
        let rawCode;
        let rawDetails;
        try {
            rawMessage = rejected.message;
            rawCode = rejected.code;
            rawDetails = rejected.details;
        } catch (err) {
            // a getter that throws: the defaults
        }
        message = sanitizeText(rawMessage, MAX_RESPONSE_MESSAGE, defaultMessage);
        if (typeof rawCode === "string" && REASON_PATTERN.test(rawCode)) {
            reason = rawCode;
        }
        details = copyDetails(rawDetails, id);
    }
    const err = responseError("deploy_rejected", 400, message);
    err.reason = reason;
    if (details !== undefined) {
        err.details = details;
    }
    log.debug("deploy rejected by " + sanitizeText(id, 100, "preDeploy") + ", reason " + reason);
    return err;
}

// `details` of a rejection: a plain object or an array, up to 8 KB as JSON; the parsed copy.
// Anything that cannot be described (a cycle, a BigInt, a revoked Proxy, a getter that throws) is dropped
function copyDetails(details, id) {
    if (details === undefined || details === null) {
        return undefined;
    }
    let json;
    try {
        const prototype = typeof details === "object" ? Object.getPrototypeOf(details) : undefined;
        const plain = Array.isArray(details) || (typeof details === "object" && (prototype === Object.prototype || prototype === null));
        if (plain) {
            json = JSON.stringify(details);
        }
    } catch (err) {
        json = undefined;
    }
    if (json === undefined || Buffer.byteLength(json, "utf8") > MAX_DETAILS_BYTES) {
        log.warn(catalog("deploy.hook-details-dropped", { id: sanitizeText(id, 100, "preDeploy") }));
        return undefined;
    }
    return JSON.parse(json);
}

/**
 * The 503 `deploy_hook_failed` error for a failure of the validator: a constant message; what
 * failed is only in the log (the identifier of the hook, the error code and a sanitised message
 * up to 200 characters; the stack at debug level).
 * @param {*} failure - what the handler threw, rejected with or passed to `done`
 * @param {string} id - the hook id
 */
function toFailure(failure, id) {
    let code = "-";
    let text;
    try {
        if (failure instanceof Error) {
            text = failure.message;
            if (typeof failure.code === "string" && REASON_PATTERN.test(failure.code)) {
                code = failure.code;
            }
        } else {
            text = failure;
        }
    } catch (err) {
        // a getter that throws: no text
    }
    log.error(catalog("deploy.hook-failed-log", {
        id: sanitizeText(id, 100, "preDeploy"),
        code: code,
        message: sanitizeText(text, MAX_LOG_MESSAGE, "no message")
    }));
    log.debug(stackText(failure));
    return responseError("deploy_hook_failed", 503, catalog("deploy.hook-failed"));
}

/**
 * The 503 `deploy_hook_timeout` error.
 */
function toTimeout() {
    return responseError("deploy_hook_timeout", 503, catalog("deploy.hook-timeout"));
}

/**
 * Runs the preDeploy chain (step 3). Resolves when every handler accepted; rejects with the
 * error to answer with (400 `deploy_rejected`, 503 `deploy_hook_failed`, 503
 * `deploy_hook_timeout`). Called only when a preDeploy handler is registered.
 * @param {Object} info - `{type, source, operation, flowId, created, flows, activeRev, rev, user}`;
 *     `flows` is the candidate configuration (copied here; the original is not touched)
 * @return {Promise<void>}
 */
async function runPreDeploy(info) {
    const timeout = getHookTimeout();
    const controller = new AbortController();
    const deadline = Date.now() + timeout;
    let timer;
    const expired = new Promise(function(resolve) {
        timer = setTimeout(function() {
            controller.abort("timeout");
            resolve(null);
        }, timeout);
        // does not keep the process alive for the limit only
        if (timer && typeof timer.unref === "function") {
            timer.unref();
        }
    });
    try {
        let flows;
        let user;
        try {
            flows = copyForHook(info.flows);
            user = sanitizeUser(info.user);
        } catch (err) {
            throw toFailure(err, "preDeploy");
        }
        const event = {
            type: info.type,
            source: info.source,
            operation: info.operation,
            flows: flows,
            activeRev: info.activeRev === undefined ? null : info.activeRev,
            user: user,
            deadline: deadline,
            // not frozen itself (Object.freeze is shallow): the handler listens to it
            signal: controller.signal
        };
        ["flowId", "created", "rev"].forEach(function(key) {
            if (info[key] !== undefined) {
                event[key] = info[key];
            }
        });
        Object.freeze(event);
        for (const handler of hooks.handlers("preDeploy")) {
            if (handler.isRemoved()) {
                continue;
            }
            const id = handler.id;
            const running = runningCalls.get(handler);
            if (running) {
                // SEC-103: the call of an earlier deployment has not ended
                log.warn(catalog("deploy.hook-busy", { id: sanitizeText(id, 100, "preDeploy"), age: Date.now() - running.startedAt }));
                throw toTimeout();
            }
            if (controller.signal.aborted || Date.now() >= deadline) {
                log.warn(catalog("deploy.hook-timeout-log", { id: sanitizeText(id, 100, "preDeploy"), timeout: timeout }));
                throw toTimeout();
            }
            const started = startCall(handler, event);
            const outcome = await Promise.race([started.promise, expired]);
            if (outcome === null) {
                started.call.abandoned = true;
                log.warn(catalog("deploy.hook-timeout-log", { id: sanitizeText(id, 100, "preDeploy"), timeout: timeout }));
                throw toTimeout();
            }
            if ("failure" in outcome) {
                throw toFailure(outcome.failure, id);
            }
            if ("reject" in outcome) {
                throw toRejection(outcome.reject, id);
            }
        }
    } catch (err) {
        // The last resort (S-C1): any exception that is not an answer built here - from a handler, its
        // result or the code that reads it - is a failure of the validator: 503, never an unhandled rejection
        if (responseErrors.has(err)) {
            throw err;
        }
        throw toFailure(err, "preDeploy");
    } finally {
        clearTimeout(timer);
    }
}

/**
 * `start.status` of the postDeploy event: what is known about the start of the flows when the
 * deployment returned (D17, D23, D24). The statuses:
 *
 *   started       the flows started (`deploy.response: "started"`: the deployment waited for it)
 *   pending       the start goes on: the default mode (the response does not wait), or a start that did
 *                 not finish within `deploy.startTimeout` (errors: [{code: "start_timeout"}] - not a
 *                 failure, the final result is in `deploy-start-result`)
 *   not_started   no start was registered: an editor-only instance, stopped flows, or an error
 *                 while stopping in the default mode (swallowed, D-05; the instance state is idle)
 *   start_failed  the start failed (deploy_start_failed without start_timeout; errors)
 *   stop_failed   stopping the flows failed (`deploy.response: "started"` only: in the default mode
 *                 the error is swallowed, so "not_started")
 *   unknown       an unexpected error of the deployment step itself after the save: nothing can be
 *                 said about the start (the error is in `error: {code}`)
 *
 * An unexpected error after the save that is not about the start (for example in an `apply` step)
 * leaves the status that the registered start gives (`held`: started / pending, otherwise
 * not_started) and is reported separately as `error: {code}` (D24).
 * @param {Error|null} err - the error of the deployment (after the save), or null
 * @param {Object} context
 * @param {boolean} context.waitForStart - `deploy.response: "started"`
 * @param {boolean} context.held - a start is registered with the deploy lock in the section
 * @param {boolean} context.direct - `err` comes from `flows.setFlows`/`loadFlows` itself
 * @return {{start: {status: String, errors?: Array}, error?: {code: String}}}
 */
function classifyStart(err, context) {
    context = context || {};
    const registered = context.held ? (context.waitForStart ? "started" : "pending") : "not_started";
    if (!err) {
        return { start: { status: registered } };
    }
    if (err.code === "deploy_start_failed") {
        let errors = [];
        if (Array.isArray(err.errors)) {
            try {
                errors = JSON.parse(JSON.stringify(err.errors));
            } catch (copyError) {
                errors = [];
            }
        }
        const timedOut = errors.some(function(entry) { return entry && entry.code === "start_timeout" });
        return { start: { status: timedOut ? "pending" : "start_failed", errors: errors } };
    }
    if (err.code === "deploy_stop_failed") {
        return { start: { status: "stop_failed" } };
    }
    const code = typeof err.code === "string" && REASON_PATTERN.test(err.code) ? err.code : "unexpected_error";
    return { start: { status: context.direct ? "unknown" : registered }, error: { code: code } };
}

function failureCode(failure) {
    let code = "-";
    try {
        if (failure && typeof failure.code === "string" && REASON_PATTERN.test(failure.code)) {
            code = failure.code;
        }
    } catch (err) {
        // a getter that throws: no code
    }
    return code;
}

/**
 * Step 11: calls the postDeploy handlers after the result of the deployment. Returns at once;
 * the handlers run from `setImmediate` (the facts were collected under the lock, setImmediate keeps
 * the order of the deployments), in parallel, each with its own error handling: a failure is a
 * warning, a returned value is ignored, a handler never delays the result or the next deployment.
 * @param {Object} facts - `{rev, type, source, operation, flowId, user, reloadType?, start, error?}`
 */
function notifyPostDeploy(facts) {
    setImmediate(function() {
        try {
            runPostDeploy(facts);
        } catch (err) {
            log.warn(catalog("deploy.post-hook-failed", {
                id: "postDeploy",
                code: failureCode(err),
                message: sanitizeText(err && err.message, MAX_LOG_MESSAGE, "no message")
            }));
            log.debug(err && err.stack ? String(err.stack) : "no stack");
        }
    });
}

function runPostDeploy(facts) {
    const list = hooks.handlers("postDeploy").filter(function(handler) { return !handler.isRemoved() });
    if (list.length === 0) {
        return;
    }
    const timeout = getHookTimeout();
    const controller = new AbortController();
    const event = {
        rev: facts.rev,
        type: facts.type,
        source: facts.source,
        operation: facts.operation || null,
        flowId: facts.flowId === undefined ? null : facts.flowId,
        user: sanitizeUser(facts.user),
        start: deepFreeze(JSON.parse(JSON.stringify(facts.start))),
        deadline: Date.now() + timeout,
        // not frozen itself (Object.freeze is shallow): the handler listens to it
        signal: controller.signal
    };
    if (facts.reloadType !== undefined) {
        event.reloadType = facts.reloadType;
    }
    if (facts.error !== undefined) {
        event.error = deepFreeze({ code: facts.error.code });
    }
    Object.freeze(event);
    const unfinished = new Set();
    let timer;
    function ended(handler) {
        unfinished.delete(handler);
        unfinishedPostCalls.set(handler, Math.max(0, (unfinishedPostCalls.get(handler) || 1) - 1));
        if (unfinished.size === 0) {
            clearTimeout(timer);
        }
    }
    list.forEach(function(handler) {
        const id = sanitizeText(handler.id, 100, "postDeploy");
        if ((unfinishedPostCalls.get(handler) || 0) >= MAX_UNFINISHED_POST_CALLS) {
            log.warn(catalog("deploy.post-hook-skipped", { id: id, limit: MAX_UNFINISHED_POST_CALLS }));
            return;
        }
        unfinishedPostCalls.set(handler, (unfinishedPostCalls.get(handler) || 0) + 1);
        unfinished.add(handler);
        invoke(handler, event, function(kind, value) {
            ended(handler);
            // a returned value is ignored; an error (thrown, rejected, or passed to done) is a warning.
            // What a handler throws can be anything (a getter that throws, a revoked Proxy): nothing of it is
            // read outside this try, so that no exception leaves the callback of the handler's promise
            try {
                if (kind === "error" || (kind === "done" && value instanceof Error)) {
                    let text;
                    try {
                        text = value instanceof Error ? value.message : value;
                    } catch (err) {
                        // a getter that throws: no text
                    }
                    log.warn(catalog("deploy.post-hook-failed", { id: id, code: failureCode(value), message: sanitizeText(text, MAX_LOG_MESSAGE, "no message") }));
                    log.debug(stackText(value));
                }
            } catch (err) {
                log.warn(catalog("deploy.post-hook-failed", { id: id, code: "-", message: sanitizeText(err && err.message, MAX_LOG_MESSAGE, "no message") }));
            }
        });
    });
    if (unfinished.size > 0) {
        timer = setTimeout(function() {
            // the same limit as of preDeploy: a warning and the signal, the handler is not interrupted
            controller.abort("timeout");
            unfinished.forEach(function(handler) {
                log.warn(catalog("deploy.post-hook-slow", { id: sanitizeText(handler.id, 100, "postDeploy"), timeout: timeout }));
            });
        }, timeout);
        if (timer && typeof timer.unref === "function") {
            timer.unref();
        }
    }
}

module.exports = {
    init,
    isValidHookTimeout,
    getHookTimeout,
    copyForHook,
    sanitizeText,
    sanitizeUser,
    runPreDeploy,
    classifyStart,
    notifyPostDeploy,
    // exported for the tests
    DEFAULT_HOOK_TIMEOUT
};
